using Backend.Api.Orchestrators;
using Backend.Api.Workflows;
using Backend.Api.Agents;

namespace Backend.Api.Data.InMemory;

public sealed class InMemoryOrchestratorRepository : IOrchestratorRepository
{
    private readonly Lock _gate = new(); private readonly List<E> _items = []; private readonly InMemoryWorkflowRepository _workflows; private readonly InMemoryAgentRepository _agents; private static DateTime Now() => DateTime.UtcNow;
    public InMemoryOrchestratorRepository(IWorkflowRepository workflows, IAgentRepository agents) { _workflows = (InMemoryWorkflowRepository)workflows; _agents = (InMemoryAgentRepository)agents; }
    public Task<IReadOnlyList<OrchestratorInfo>> ListAsync(string t, CancellationToken ct) { lock (_gate) return Task.FromResult<IReadOnlyList<OrchestratorInfo>>(_items.Where(x => x.Tenant == t).Select(x => x.Info()).ToArray()); }
    public Task<Orchestrator?> GetAsync(string t, Guid id, CancellationToken ct) { lock (_gate) return Task.FromResult(Find(t, id)?.Model()); }
    public Task<OrchestratorWriteResult> CreateAsync(string t, string n, string d, string def, string by, CancellationToken ct) { lock (_gate) { if (_items.Any(x => x.Tenant == t && x.Name == n)) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.Duplicate)); var now = Now(); var e = new E { Id = Guid.NewGuid(), Tenant = t, Name = n, Description = d, Definition = def, Created = now, Updated = now }; _items.Add(e); return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.Success, e.Model())); } }
    public Task<OrchestratorWriteResult> UpdateAsync(string t, Guid id, long v, string n, string d, string def, CancellationToken ct) { lock (_gate) { var e = Find(t, id); if (e is null) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.NotFound)); if (e.Version != v) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.VersionConflict, CurrentDraftVersion: e.Version)); e.Name = n; e.Description = d; e.Definition = def; e.Version++; e.Validated = null; e.Updated = Now(); return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.Success, e.Model())); } }
    public Task<IReadOnlyList<string>> ValidateReferencesAsync(string t, string def, CancellationToken ct) { lock (_workflows.ReferenceSyncRoot) lock (_agents.OrchestratorReferenceSyncRoot) return Task.FromResult<IReadOnlyList<string>>(ValidateReferencesUnsafe(t, def)); }
    public Task<bool> MarkValidatedAsync(string t, Guid id, long v, string def, CancellationToken ct) { lock (_gate) { var e = Find(t, id); if (e is null || e.Version != v) return Task.FromResult(false); e.Definition = def; e.Validated = v; return Task.FromResult(true); } }
    public Task<OrchestratorWriteResult> PublishAsync(string t, Guid id, long v, string def, string by, CancellationToken ct) { lock (_workflows.ReferenceSyncRoot) lock (_agents.OrchestratorReferenceSyncRoot) lock (_gate) { var e = Find(t, id); if (e is null) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.NotFound)); if (e.Version != v || e.Validated != v || e.Definition != def || ValidateReferencesUnsafe(t, def).Count > 0) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.VersionConflict)); foreach (var x in e.Revs.Where(x => x.Status == "published")) x.Status = "superseded"; var r = (e.Published ?? 0) + 1; e.Revs.Add(new R { N = r, Definition = def, Hash = WorkflowCanonicalizer.Hash(def), By = by, At = Now() }); e.Published = r; e.Validated = null; return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.Success, e.Model(), r)); } }
    public Task<IReadOnlyList<OrchestratorRevisionInfo>> RevisionsAsync(string t, Guid id, CancellationToken ct) { lock (_gate) { return Task.FromResult<IReadOnlyList<OrchestratorRevisionInfo>>(Find(t, id)?.Revs.Select(x => new OrchestratorRevisionInfo(x.N, x.Status, x.Hash, x.By, x.At)).ToArray() ?? []); } }
    public Task<string?> RevisionAsync(string t, Guid id, int r, CancellationToken ct) { lock (_gate) return Task.FromResult(Find(t, id)?.Revs.FirstOrDefault(x => x.N == r)?.Definition); }
    public Task<OrchestratorWriteResult> RestoreAsync(string t, Guid id, int r, string def, string by, CancellationToken ct) { lock (_workflows.ReferenceSyncRoot) lock (_agents.OrchestratorReferenceSyncRoot) lock (_gate) { var e = Find(t, id); if (e is null || e.Revs.All(x => x.N != r)) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.NotFound)); if (ValidateReferencesUnsafe(t, def).Count > 0) return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.VersionConflict)); foreach (var x in e.Revs.Where(x => x.Status == "published")) x.Status = "superseded"; var n = (e.Published ?? 0) + 1; e.Revs.Add(new R { N = n, Definition = def, Hash = WorkflowCanonicalizer.Hash(def), By = by, At = Now() }); e.Published = n; return Task.FromResult(new OrchestratorWriteResult(OrchestratorWriteStatus.Success, e.Model(), n)); } }
    private List<string> ValidateReferencesUnsafe(string t, string def) { var errors = new List<string>(); using var doc = System.Text.Json.JsonDocument.Parse(def); var w = doc.RootElement.GetProperty("workflow"); if (!_workflows.HasActivePublishedUnsafe(t, Guid.Parse(w.GetProperty("id").GetString()!), w.GetProperty("revision").GetInt32())) errors.Add("workflow must pin active same-tenant published orchestrator kind"); foreach (var reference in OrchestratorCanonicalizer.AgentRefs(def)) { var agent = _agents.GetActivePublishedOrchestratorReferenceWithoutLock(t, reference.AgentId, reference.Revision); if (agent is null) { errors.Add($"agent {reference.AgentId:D} must pin active same-tenant published revision"); continue; } errors.AddRange(OrchestratorReferencePolicy.ValidateAgentDefinition(agent.Value.Definition, reference)); errors.AddRange(OrchestratorReferencePolicy.ValidateRuntimeWorkflowProjection(agent.Value.Definition, agent.Value.WorkflowId, agent.Value.WorkflowRevision)); if (reference.Verifier) errors.AddRange(ValidateVerifierWorkflow(t, agent.Value.WorkflowId, agent.Value.WorkflowRevision)); } return errors; }
    private IReadOnlyList<string> ValidateVerifierWorkflow(string tenant, Guid? id, int? revision) { if (id is null || revision is null) return ["verifier Agent revision must pin a verifier agent-runtime Workflow revision"]; var artifact = _workflows.GetVisibleAgentRuntimeRevisionUnsafe(tenant, id.Value, revision.Value); if (artifact is null) return ["verifier Agent revision must pin a visible agent-runtime Workflow revision"]; return OrchestratorReferencePolicy.ValidateVerifierWorkflowDefinition(artifact.Value.Definition, artifact.Value.Contract); }
    public Task<bool> SetEnabledAsync(string t, Guid id, bool enabled, CancellationToken ct) { lock (_gate) { var e = Find(t, id); if (e is null) return Task.FromResult(false); e.Enabled = enabled; return Task.FromResult(true); } }
    private E? Find(string t, Guid id) => _items.FirstOrDefault(x => x.Tenant == t && x.Id == id); private sealed class E { public Guid Id; public string Tenant = "", Name = "", Description = "", Definition = "{}"; public bool Enabled = true; public long Version = 1; public long? Validated; public int? Published; public DateTime Created, Updated; public List<R> Revs = []; public Orchestrator Model() => new(Id, Name, Description, Enabled, Version, Validated, Published, Definition, Created, Updated); public OrchestratorInfo Info() => new(Id, Name, Description, Enabled, Version, Validated, Published, Created, Updated); }
    private sealed class R { public int N; public string Status = "published", Definition = "{}", Hash = "", By = ""; public DateTime At; }
}
